use vstd::prelude::*;

verus! {
    // Specification for the clip function
    spec fn clip_spec(a: Vec<i8>, min: i8, max: i8) -> Vec<i8>
        requires
            a.len() > 0,
            min < max,
    {
        let mut result: Vec<i8> = Vec::new();
        for i in 0..a.len() {
            let value = a[i];
            if value < min {
                result.push(min);
            } else if value > max {
                result.push(max);
            } else {
                result.push(value);
            }
        }
        result
    }

    fn clip(a: Vec<i8>, min: i8, max: i8) -> (result: Vec<i8>)
        requires
            a.len() > 0,
            min < max,
        ensures
            result.len() == a.len(),
            forall |i: nat| (i < a.len() as nat) ==> (result[i] == clip_spec(a, min, max)[i]),
    {
        let mut result: Vec<i8> = Vec::new();
        let n = a.len() as nat;

        // Loop through each element in the input array
        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                result.len() == i,
                forall |j: nat| (j < i) ==> (result[j] == clip_spec(a, min, max)[j]),
            decreases n - i,
        {
            let value = a[i as usize];
            if value < min {
                result.push(min);
            } else if value > max {
                result.push(max);
            } else {
                result.push(value);
            }
            i = i + 1;
        }
        result
    }
}

